 void chooseLocalFolder(){if(settingsDialog!=null)settingsDialog.dismiss();try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);intent.putExtra(Intent.EXTRA_LOCAL_ONLY,true);startActivityForResult(intent,PICK_LOCAL);}catch(ActivityNotFoundException e){toast("폴더 선택기를 열 수 없습니다");}}
