 void renderFolders(){sidebar.removeAllViews();Button label=button("폴더 "+folders.size()+"개 · 전체 목록",false,this::folderDialog);sidebar.addView(label,lp(-1,42));String base=demo?"":config.root;List<String> sorted=new ArrayList<>(folders);sorted.remove(base);sorted.sort(Paths::natural);sorted.add(0,base);ListView list=new ListView(this);list.setDivider(null);list.setScrollbarFadingEnabled(false);list.setAdapter(new BaseAdapter(){public int getCount(){return sorted.size();}public Object getItem(int position){return sorted.get(position);}public long getItemId(int position){return position;}public View getView(int position,View old,ViewGroup parent){String f=sorted.get(position);String relative=base.isEmpty()?f:f.substring(Math.min(f.length(),base.length()+1));String name=position==0?"전체 선택":f.substring(f.lastIndexOf('/')+1);return folderRow(f,name,position==0?0:Math.min(3,Paths.depth(relative)-1)+1);}});sidebar.addView(list,new LinearLayout.LayoutParams(-1,0,1));CheckBox recursive=new CheckBox(this);recursive.setText("하위 폴더 포함");recursive.setTextSize(13);recursive.setTextColor(MUTED);recursive.setChecked(selection.recursive);recursive.setPadding(0,dp(10),0,0);recursive.setOnCheckedChangeListener((b,on)->{selection.recursive=on;saveSelection();renderFolders();refreshSelection();});sidebar.addView(recursive,lp(-1,52));}
 void folderDialog(){List<String> names=new ArrayList<>(folders);names.sort(Paths::natural);String base=demo?"":config.root;names.remove(base);names.add(0,base);String[] labels=new String[names.size()];boolean[] checked=new boolean[names.size()];for(int i=0;i<labels.length;i++){labels[i]=names.get(i).equals(base)?"공유/선택 폴더 전체":names.get(i);checked[i]=selection.state(names.get(i),folders)==1;}Selection pending=new Selection();pending.recursive=selection.recursive;pending.rules.putAll(selection.rules);new AlertDialog.Builder(this).setTitle("모든 폴더 ("+names.size()+")").setMultiChoiceItems(labels,checked,(d,which,on)->{if(which==0){pending.rules.clear();if(pending.recursive)pending.all(base,on);else for(String f:names)pending.rules.put(f,on);for(int i=0;i<names.size();i++)((AlertDialog)d).getListView().setItemChecked(i,on);}else{pending.set(names.get(which),on);for(int i=0;i<names.size();i++)((AlertDialog)d).getListView().setItemChecked(i,pending.state(names.get(i),folders)==1);}}).setPositiveButton("적용",(d,w)->{selection=pending;saveSelection();renderFolders();refreshSelection();}).setNegativeButton("취소",null).show();}
